let storageOK=true;function readStore(key){try{return JSON.parse(localStorage.getItem(key)||'null')}catch{return null}};
function writeStore(obj){try{localStorage.setItem(KEY,JSON.stringify(obj));storageOK=true;return true}catch{storageOK=false;return false}}
function migrate(w,i){const from=n=>clamp((n-650)/18,-103,103); const fromZ=n=>clamp((n-720)/18,-103,103);const fresh=freshWorld(i,w.seed||1);fresh.name=String(w.name||fresh.name).slice(0,45);fresh.day=clamp(num(w.day)||1,1,99999);fresh.clock=clamp(Number(w.clock)||.17,0,.99);fresh.player.x=from(w.player?.x||650);fresh.player.z=fromZ(w.player?.y||720);fresh.player.hp=clamp(Number(w.player?.hp)||100,1,100);fresh.player.hunger=clamp(Number(w.player?.hunger)||100,1,100);fresh.inv={...fresh.inv,...Object.fromEntries(TYPES.map(t=>[t,clamp(num(w.inv?.[t]),0,100000)]))};fresh.scanner=!!w.tool;fresh.relay=!!w.relay;fresh.chapter=clamp(num(w.chapter),0,3);fresh.discoveries=Array.isArray(w.discoveries)?w.discoveries.slice(0,40).map(x=>String(x).slice(0,140)):fresh.discoveries;fresh.buildings=(w.buildings||[]).slice(0,120).filter(x=>COST[x.kind]).map(b=>({kind:b.kind,x:from(b.x),z:fromZ(b.y),fuel:clamp(Number(b.fuel)||0,0,200)}));fresh.legacyImported=true;return fresh}
function freshWorld(i,seed=((Date.now()^Math.floor(Math.random()*1e9))>>>0)){return {v:2,name:`Frontier ${i+1}`,seed,day:1,clock:.17,scene:'home',player:{x:0,z:0,hp:100,hunger:100,stamina:100},inv:{wood:11,stone:9,scrap:5,berry:4,lumen:0},scanner:false,relay:false,chapter:0,expNights:0,discoveries:['The Arrival'],buildings:[{kind:'campfire',x:5,z:3,fuel:0}],depleted:{},played:0,lastSaved:Date.now()}}
let worlds=readStore(KEY);if(!worlds||typeof worlds!=='object'||Array.isArray(worlds))worlds={};
if(!Object.keys(worlds).length){const old=readStore(OLD);if(old&&typeof old==='object'){for(let i=0;i<3;i++)if(old[i])worlds[i]=migrate(old[i],i);if(Object.keys(worlds).length)writeStore(worlds)}}
let current=null,slot=null,canvas=null,gl=null,program=null,terrainBuffer=null,staticBuffer=null,dynamicBuffer=null,terrainCount=0,staticCount=0,attributes={},uniforms={},width=0,height=0;
let keys=new Set(),pressed=new Set(),mobileKeys=new Set(),camYaw=.45,camPitch=.51,third=true,buildKind=null,showDialog=false,cutscene=null,modalKind='',sceneNodes=[],creatures=[],sun=1,ambient=.8,clockT=0,toastUntil=0,toastText='',raf=0,lastTick=0,autosave=0,uiClock=0,collectorClock=0,spawnClock=0,lookPointer=null,dragging=false,scanTime=0,playerHeading=0,motion=0,audio=null,audioOn=false,sceneKey='',gameStarted=false,saveStatus='Local save';
