function home(){gameStarted=false;cancelAnimationFrame(raf);raf=0;current=null;slot=null;keys.clear();pressed.clear();mobileKeys.clear();window.removeEventListener('keydown',keyDown);window.removeEventListener('keyup',keyUp);if(document.pointerLockElement===canvas)document.exitPointerLock?.();
root.innerHTML=`<div class="cover"><span class="overline">LUCION GAMES / ARCADIA ORIGINAL / 3D WORLD</span><h1>HOLLOW<br>FRONTIER<span style="color:#95dfb0">.</span></h1><p class="lede">A lost expedition. A forest that changes after dark. Build your settlement, automate your survival, and uncover the truth behind the Meridian signal.</p><span class="overline">SELECT A WORLD · THREE FREE SAVES</span><div class="slots" id="hf3-slots"></div><p class="note">Browser edition v${VERSION}. Worlds save locally to this browser, without sign-in or Robux purchases. ${Object.values(worlds).some(w=>w?.legacyImported)?'Your original 2D progress was imported into separate 3D saves. The original data remains untouched.':''}</p><div style="display:flex;gap:9px;flex-wrap:wrap;position:relative;z-index:2"><label class="btn" style="display:inline-flex;align-items:center" for="hf3-import">Import 3D world backup</label><input id="hf3-import" type="file" accept=".json,application/json" style="display:none"><button class="btn" data-action="classic">Play original 2D edition</button></div></div>`;
const slots=root.querySelector('#hf3-slots');for(let i=0;i<3;i++){const w=worlds[i],b=document.createElement('button');b.type='button';b.className='slot';b.dataset.action='slot';b.dataset.index=i;b.innerHTML=`<span class="overline">SLOT 0${i+1} / ${w?'CONTINUE':'CREATE WORLD'}</span><strong>${esc(w?.name||'Uncharted wilderness')}</strong><small>${w?`Day ${num(w.day)} · ${w.buildings?.length||0} structures · ${w.relay?'Relay online':'Signal missing'}`:'New story · Empty world'}</small>`;slots.append(b)}
}
function loadClassic(){cancelAnimationFrame(raf);window.removeEventListener('keydown',keyDown);window.removeEventListener('keyup',keyUp);if(document.pointerLockElement===canvas)document.exitPointerLock?.();root.remove();const s=document.createElement('script');s.src='hollow-frontier-classic.js';s.onerror=()=>{stage.textContent='Classic edition unavailable. The 3D experience needs WebGL to render.'};document.body.append(s)}
function safeImport(data){if(!data||data.type!=='hollow-frontier-3d-save'||data.version!==2||!data.world||typeof data.world!=='object')throw Error('Not a Hollow Frontier 3D backup');const w=data.world;if(!w.player||!w.inv||!Array.isArray(w.buildings))throw Error('Backup world data is incomplete');const imported=freshWorld(0,num(w.seed)||1);imported.seed=num(w.seed)>>>0;imported.name=String(w.name||'Recovered Frontier').slice(0,45);imported.day=clamp(num(w.day),1,99999);imported.clock=clamp(Number(w.clock)||.17,0,.99);imported.scene=w.scene==='expedition'?'expedition':'home';for(const k of ['x','z'])imported.player[k]=clamp(Number(w.player[k])||0,-104,104);for(const k of ['hp','hunger','stamina'])imported.player[k]=clamp(Number(w.player[k])||100,0,100);for(const t of TYPES)imported.inv[t]=clamp(num(w.inv[t]),0,100000);imported.scanner=!!w.scanner;imported.relay=!!w.relay;imported.chapter=clamp(num(w.chapter),0,3);imported.expNights=clamp(num(w.expNights),0,99999);imported.discoveries=Array.isArray(w.discoveries)?w.discoveries.slice(0,100).map(x=>String(x).slice(0,140)):['The Arrival'];imported.buildings=w.buildings.slice(0,120).filter(b=>b&&COST[b.kind]).map(b=>({kind:b.kind,x:clamp(Number(b.x)||0,-104,104),z:clamp(Number(b.z)||0,-104,104),fuel:clamp(Number(b.fuel)||0,0,9999)}));const depleted=w.depleted&&typeof w.depleted==='object'?w.depleted:{};for(const [k,v] of Object.entries(depleted).slice(0,300))if(/^[he](?:\d+|\-start\-[a-z]+)$/.test(k))imported.depleted[k]=clamp(num(v),0,100);return imported}
root.addEventListener('change',async e=>{if(e.target?.id!=='hf3-import')return;const f=e.target.files?.[0];e.target.value='';if(!f)return;try{if(f.size>500000)throw Error('Backup file is too large');const data=JSON.parse(await f.text());const imported=safeImport(data);const choice=window.prompt('Restore into which world slot? Enter 1, 2, or 3.');const i=Number(choice)-1;if(!Number.isInteger(i)||i<0||i>2)return;if(worlds[i]&&!window.confirm(`Replace ${worlds[i].name} in slot ${i+1}? This cannot be undone.`))return;worlds[i]=imported;if(!writeStore(worlds))throw Error('Browser storage is blocked');home();toast('3D world backup imported.')}catch(err){window.alert('Could not import backup: '+err.message)}});
function save(){if(!current||slot===null)return false;current.lastSaved=Date.now();worlds[slot]=current;const ok=writeStore(worlds);saveStatus=ok?'Saved locally':'Storage blocked';const st=root.querySelector('#hf3-save');if(st)st.textContent=saveStatus;if(!ok)toast('Saving unavailable. Check browser storage settings.',5);return ok}
function openWorld(i){slot=i;current=worlds[i]||freshWorld(i);if(!current.player||!current.inv||!Array.isArray(current.buildings)){current=freshWorld(i);toast('Invalid save was reset for this slot.')}current.player.stamina=clamp(Number(current.player.stamina)||100,0,100);current.depleted??={};current.buildings??=[];current.discoveries??=[];current.scene??='home';worlds[i]=current;camYaw=.45;camPitch=.51;third=true;buildKind=null;renderShell();initGL();if(!gl){showWebGLError();return}gameStarted=true;makeWorld();makeHUD();lastTick=performance.now();window.addEventListener('keydown',keyDown);window.addEventListener('keyup',keyUp);raf=requestAnimationFrame(frame);if(current.chapter===0){scene('arrival')}else toast('Welcome back, explorer.');}
function showWebGLError(){root.innerHTML='<div class="cover"><h2>3D graphics unavailable</h2><p class="lede">This browser or device could not start WebGL. You can still play the original 2D edition.</p><button class="btn accent" data-action="classic">Play 2D edition</button> <button class="btn" data-action="menu">Back to worlds</button></div>'}
function renderShell(){root.innerHTML=`<div class="screen" id="hf3-screen"><canvas id="hf3-canvas" tabindex="0" aria-label="Immersive three-dimensional Hollow Frontier wilderness. Use W A S D to explore, mouse to look, E to interact."></canvas><div class="rain" aria-hidden="true"></div><div class="hud"><div class="top"><div class="brand">HOLLOW FRONTIER <span class="subbrand">LUCION GAMES · ARCADIA 3D</span></div><div class="topright"><span class="pill" id="hf3-date">DAY 01 · MORNING</span><span class="pill" id="hf3-zone">THE OUTPOST</span><button class="btn" data-action="save">SAVE</button><button class="btn" data-action="journal">JOURNAL</button><button class="btn pack-trigger" data-action="pack">PACK</button><button class="btn" data-action="fullscreen">⛶</button><button class="btn" data-action="menu">WORLDS</button></div></div><div class="left"><div class="small-title">CURRENT OBJECTIVE</div><p class="mission" id="hf3-objective">Find the Meridian relay</p><div class="metric"><span>HEALTH</span><span id="hf3-hp-text">100</span></div><div class="meter"><i id="hf3-hp"></i></div><div class="metric"><span>HUNGER</span><span id="hf3-hunger-text">100</span></div><div class="meter"><i id="hf3-hunger" style="background:#e6ca84"></i></div><div class="metric"><span>STAMINA</span><span id="hf3-stamina-text">100</span></div><div class="meter"><i id="hf3-stamina" style="background:#9dccfb"></i></div><span class="help-line" id="hf3-nearest">Explore to find resources</span></div><div class="right"><div class="small-title">PACK / MATERIALS</div><div id="hf3-inventory" class="inventory"></div><div class="small-title">CRAFT / CONSTRUCT</div><div id="hf3-craft" class="craft"></div><div class="small-title">POWER GRID</div><div id="hf3-power" style="font-size:11px;color:#c0ddc8"></div><div style="display:flex;gap:5px;margin-top:9px"><button class="btn" data-action="journal">Journal</button><button class="btn" data-action="help">Guide</button></div></div><div class="reticle"></div><div class="toast" id="hf3-toast" hidden></div><div class="hint" id="hf3-hint">WASD move · drag to rotate camera · E gather · Space scan</div><div class="touch"><button class="btn" data-move="up" aria-label="Forward">▲</button><button class="btn" data-move="left" aria-label="Left">◀</button><button class="btn" data-move="down" aria-label="Backward">▼</button><button class="btn" data-move="right" aria-label="Right">▶</button></div><div class="touchact"><button class="btn" data-action="interact">GATHER</button><button class="btn" data-action="scan">SCAN</button><button class="btn" data-action="turn">CAMERA</button></div><div class="bottom"><button class="btn" data-action="interact">E · INTERACT</button><button class="btn" data-action="eat">EAT</button><button class="btn" data-action="scanner">SCANNER</button><button class="btn" data-action="fuel">FUEL</button><button class="btn" data-action="expedition">EXPEDITION</button><button class="btn" data-action="camera">VIEW</button><button class="btn" data-action="audio">AUDIO OFF</button><span id="hf3-save" style="align-self:center;font-size:10px;color:#c1d5d1">LOCAL AUTOSAVE</span></div></div><div id="hf3-modal"></div></div>`;
canvas=root.querySelector('#hf3-canvas');canvas.addEventListener('pointerdown',e=>{if(e.button!==0&&e.button!==2)return;canvas.focus();dragging=true;lookPointer={id:e.pointerId,x:e.clientX,y:e.clientY,sx:e.clientX,sy:e.clientY,time:performance.now()};canvas.setPointerCapture?.(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(document.pointerLockElement===canvas){camYaw-=e.movementX*.003;camPitch=clamp(camPitch+e.movementY*.0025,.14,1.14);return}if(!dragging||!lookPointer)return;camYaw-=(e.clientX-lookPointer.x)*.007;camPitch=clamp(camPitch+(e.clientY-lookPointer.y)*.005,.14,1.14);lookPointer.x=e.clientX;lookPointer.y=e.clientY});canvas.addEventListener('pointerup',e=>{if(!lookPointer)return;const dx=Math.hypot(e.clientX-lookPointer.sx,e.clientY-lookPointer.sy);dragging=false;if(dx<8&&buildKind&&!showDialog)placeFromPointer(e);lookPointer=null});canvas.addEventListener('pointercancel',()=>{dragging=false;lookPointer=null});canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('wheel',e=>{e.preventDefault();camPitch=clamp(camPitch+e.deltaY*.0007,.16,1.14)},{passive:false});
root.querySelectorAll('[data-move]').forEach(b=>{const k=b.dataset.move;b.addEventListener('pointerdown',e=>{e.preventDefault();mobileKeys.add(k);b.setPointerCapture?.(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>mobileKeys.delete(k)))});
}
function vertexShader(){return `attribute vec3 aPos;attribute vec3 aNormal;attribute vec4 aColor;uniform mat4 uVP;uniform vec3 uCamera;uniform vec3 uSun;uniform vec3 uFog;uniform vec3 uLamp;uniform float uDay;uniform float uHasLamp;varying vec3 vCol;void main(){vec3 n=normalize(aNormal);float direct=max(dot(n,normalize(uSun)),0.0);float diff=(.22+uDay*.48)+direct*(.1+uDay*.45);float distLamp=distance(aPos,uLamp);float lamp=(1.0-smoothstep(2.0,22.0,distLamp))*uHasLamp*.78;float distCam=distance(aPos,uCamera);float fog=smoothstep(65.0,152.0,distCam);vec3 lit=aColor.rgb*(diff+lamp)+aColor.rgb*aColor.a;vCol=mix(lit,uFog,fog);gl_Position=uVP*vec4(aPos,1.0);}`}
function fragmentShader(){return `precision mediump float;varying vec3 vCol;void main(){gl_FragColor=vec4(vCol,1.0);}`}
function shader(kind,src){const x=gl.createShader(kind);gl.shaderSource(x,src);gl.compileShader(x);if(!gl.getShaderParameter(x,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(x));return x}
function initGL(){try{gl=canvas.getContext('webgl',{alpha:false,antialias:true,depth:true,powerPreference:'high-performance'})||canvas.getContext('experimental-webgl');if(!gl)return;program=gl.createProgram();gl.attachShader(program,shader(gl.VERTEX_SHADER,vertexShader()));gl.attachShader(program,shader(gl.FRAGMENT_SHADER,fragmentShader()));gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(program));gl.useProgram(program);for(const n of ['aPos','aNormal','aColor'])attributes[n]=gl.getAttribLocation(program,n);for(const n of ['uVP','uCamera','uSun','uFog','uLamp','uDay','uHasLamp'])uniforms[n]=gl.getUniformLocation(program,n);gl.enable(gl.DEPTH_TEST);gl.depthFunc(gl.LEQUAL);gl.disable(gl.CULL_FACE);gl.enableVertexAttribArray(attributes.aPos);gl.enableVertexAttribArray(attributes.aNormal);gl.enableVertexAttribArray(attributes.aColor);terrainBuffer=gl.createBuffer();staticBuffer=gl.createBuffer();dynamicBuffer=gl.createBuffer();canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();cancelAnimationFrame(raf);toast('3D graphics paused. Reload to restore the renderer.',10)});canvas.addEventListener('webglcontextrestored',()=>location.reload())}catch(e){console.error('Hollow Frontier WebGL startup:',e);gl=null;}}
function bind(buffer){gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.vertexAttribPointer(attributes.aPos,3,gl.FLOAT,false,40,0);gl.vertexAttribPointer(attributes.aNormal,3,gl.FLOAT,false,40,12);gl.vertexAttribPointer(attributes.aColor,4,gl.FLOAT,false,40,24)}
const palette={ground:[.21,.39,.32],ground2:[.19,.35,.30],path:[.46,.41,.31],tree:[.12,.39,.3],pine:[.15,.46,.36],pine2:[.24,.54,.38],bark:[.36,.28,.23],stone:[.41,.51,.5],stone2:[.52,.63,.59],steel:[.28,.45,.48],steel2:[.48,.63,.59],gold:[.85,.62,.32],bright:[.46,.95,.8],light:[.97,.83,.49],shadow:[.10,.18,.23],fog:[.52,.72,.72],red:[.9,.4,.4],player:[.75,.88,.82]};
class Builder{constructor(){this.data=[]}tri(a,b,c,color,em=0){let n=norm(cross(sub(b,a),sub(c,a)));if(!Number.isFinite(n[0]))n=[0,1,0];for(const v of [a,b,c])this.data.push(v[0],v[1],v[2],n[0],n[1],n[2],color[0],color[1],color[2],em)}quad(a,b,c,d,col,em=0){this.tri(a,b,c,col,em);this.tri(a,c,d,col,em)}box(x,y,z,sx,sy,sz,col,em=0){const x0=x-sx/2,x1=x+sx/2,y0=y,y1=y+sy,z0=z-sz/2,z1=z+sz/2;const a=[x0,y0,z0],b=[x1,y0,z0],c=[x1,y0,z1],d=[x0,y0,z1],e=[x0,y1,z0],f=[x1,y1,z0],g=[x1,y1,z1],h=[x0,y1,z1];this.quad(e,f,g,h,col,em);this.quad(a,d,c,b,col,em);this.quad(a,b,f,e,col,em);this.quad(b,c,g,f,col,em);this.quad(c,d,h,g,col,em);this.quad(d,a,e,h,col,em)}cone(x,y,z,r,height,col,sides=7){const peak=[x,y+height,z];for(let i=0;i<sides;i++){const a=i/sides*Math.PI*2,b=(i+1)/sides*Math.PI*2;this.tri([x+r*Math.cos(a),y,z+r*Math.sin(a)],[x+r*Math.cos(b),y,z+r*Math.sin(b)],peak,col)}}cylinder(x,y,z,r,height,col,sides=7){for(let i=0;i<sides;i++){const a=i/sides*Math.PI*2,b=(i+1)/sides*Math.PI*2;const p=[x+r*Math.cos(a),y,z+r*Math.sin(a)],q=[x+r*Math.cos(b),y,z+r*Math.sin(b)];this.quad(p,q,[q[0],y+height,q[2]],[p[0],y+height,p[2]],col)}}oct(x,y,z,r,col,em=0){const a=[x+r,y,z],b=[x,y,z+r],c=[x-r,y,z],d=[x,y,z-r],t=[x,y+r*1.35,z],bt=[x,y-r*.6,z];for(const [v,w] of [[a,b],[b,c],[c,d],[d,a]]){this.tri(v,w,t,col,em);this.tri(w,v,bt,col,em)}}finish(){return new Float32Array(this.data)}}
function meshTree(b,x,z,r=1,c=0){const h=terrain(x,z);b.cylinder(x,h,z,.22*r,2.9*r,palette.bark);b.cone(x,h+1.35*r,z,1.8*r,4.6*r,c?palette.pine2:palette.tree,7);b.cone(x,h+3*r,z,1.5*r,3.9*r,c?palette.pine:palette.pine2,7)}
function nodeSeed(seed,exp=false){const rand=randSeed((seed^(exp?0x83a71:0xf921d))>>>0),out=[];const kinds=['wood','wood','wood','stone','stone','scrap','berry','berry','lumen'];for(let i=0;i<130;i++){let x=rand()*218-109,z=rand()*218-109;if(Math.hypot(x,z)<11){x+=22;z+=14}if(Math.hypot(x-55,z-30)<10){x-=11;z+=15}const type=kinds[Math.floor(rand()*kinds.length)];if(!exp&&type==='lumen'&&rand()<.7)continue;out.push({id:`${exp?'e':'h'}${i}`,type,x,z,qty:type==='wood'||type==='stone'?3:1})}if(!exp)out.push({id:'h-start-wood',type:'wood',x:8,z:7,qty:5},{id:'h-start-stone',type:'stone',x:-8,z:6,qty:5},{id:'h-start-scrap',type:'scrap',x:12,z:-4,qty:4},{id:'h-start-berry',type:'berry',x:-6,z:-4,qty:4});return out}
function makeWorld(){sceneKey=current.scene;sceneNodes=nodeSeed(current.seed,current.scene==='expedition');for(const n of sceneNodes)n.qty=Math.max(0,n.qty-(num(current.depleted[n.id])||0));
const r=randSeed((current.seed^(current.scene==='expedition'?0xde0031:0x41fa2))>>>0);
const ground=new Builder();const M=112,step=2.1;for(let x=-M;x<M;x+=step)for(let z=-M;z<M;z+=step){const h1=terrain(x,z),h2=terrain(x+step,z),h3=terrain(x+step,z+step),h4=terrain(x,z+step);const q=Math.sin(x*.125+z*.088)*.03;let col=[palette.ground[0]+q,palette.ground[1]+q,palette.ground[2]+q];if(current.scene==='expedition')col=[.20+q,.34+q,.37+q];ground.quad([x,h1,z],[x,h4,z+step],[x+step,h3,z+step],[x+step,h2,z],col)}
const t=ground.finish();terrainCount=t.length/10;gl.bindBuffer(gl.ARRAY_BUFFER,terrainBuffer);gl.bufferData(gl.ARRAY_BUFFER,t,gl.STATIC_DRAW);
const b=new Builder();
for(let i=0;i<205;i++){const x=r()*220-110,z=r()*220-110;if(Math.hypot(x,z)<12||Math.hypot(x-55,z-30)<8)continue;if(r()<.16){b.oct(x,terrain(x,z)+.35,z,.9,palette.stone)}else{meshTree(b,x,z,.6+r()*.48,i%4===0?1:0)}}
for(let i=0;i<120;i++){let x=r()*222-111,z=r()*222-111;if(Math.hypot(x,z)<9)continue;const h=terrain(x,z);b.cone(x,h,z,.26+r()*.12,.5+r()*.2,[.26,.51,.36],4)}
// Meandering dirt trail to the relay; visual guidance through the old forest.
if(current.scene==='home')for(let i=0;i<40;i++){const tt=i/39,x=tt*55,z=tt*30+Math.sin(tt*5)*3,h=terrain(x,z)+.02;b.box(x,h,z,3.2,.05,2.5,palette.path)}
for(const n of sceneNodes){if(n.qty<=0)continue;const h=terrain(n.x,n.z);if(n.type==='wood')meshTree(b,n.x,n.z,.83,.3);if(n.type==='stone'){b.oct(n.x,h+.68,n.z,.8,palette.stone);b.oct(n.x+.55,h+.30,n.z+.4,.44,palette.stone2)}if(n.type==='scrap'){b.box(n.x,h,n.z,1.3,.8,1.3,palette.steel);b.box(n.x,h+.8,n.z,1.45,.13,1.45,palette.gold)}if(n.type==='berry'){b.cylinder(n.x,h,n.z,.3,.6,palette.tree);for(let k=0;k<3;k++)b.oct(n.x+Math.cos(k*2.1)*.5,h+.85,n.z+Math.sin(k*2.1)*.5,.31,[.62,.48,.84],.2)}if(n.type==='lumen'){b.oct(n.x,h+.64,n.z,.75,palette.bright,.72);b.oct(n.x+.7,h+.28,n.z,.34,palette.steel2,.5)}}
if(current.scene==='home'){const x=55,z=30,h=terrain(x,z);b.box(x,h,z,8,.95,8,palette.steel);b.box(x,h+1,z,5,4,5,palette.steel2);b.cylinder(x,h+5,z,.65,15,palette.steel);b.box(x,h+13,z,9,.8,1,palette.steel2);b.box(x,h+17,z,1.8,1.7,1.8,current.relay?palette.bright:palette.red,current.relay?.9:.28);b.box(x,h+2.8,z+2.65,2.3,1.3,.25,palette.shadow);b.box(x,h+3,z+2.82,1.5,.65,.15,current.relay?palette.bright:palette.gold,.7);
const px=15,pz=17,py=terrain(px,pz);b.cylinder(px,py,pz,3,.3,palette.steel);b.cylinder(px,py+.4,pz,2.3,.2,palette.bright,9);
} else {const x=-13,z=-6,h=terrain(x,z);b.box(x,h,z,9,2,9,palette.steel);b.box(x,h+2,z,5,5,5,palette.steel2);b.oct(x,h+9,z,2.8,palette.bright,.8)}
for(const obj of current.scene==='home'?current.buildings:[]){const x=obj.x,z=obj.z,h=terrain(x,z);if(obj.kind==='campfire'){b.cylinder(x,h,z,1.1,.3,palette.stone2);b.cone(x,h+.17,z,.72,1,palette.gold,5)}if(obj.kind==='wall'){b.box(x,h,z,3.5,2,1.0,palette.bark);b.box(x,h+2,z,3.5,.3,1.1,palette.stone)}if(obj.kind==='generator'){b.box(x,h,z,3.5,2.2,2.4,palette.steel);b.box(x,h+2.2,z,3,.4,2.5,palette.steel2);b.box(x,h+1.1,z+1.3,1.3,.7,.13,obj.fuel>0?palette.bright:palette.gold,obj.fuel>0?.65:0);b.cylinder(x+1.5,h+2.3,z,.38,1.3,palette.stone)}if(obj.kind==='collector'){b.box(x,h,z,3,1.5,3,palette.steel2);b.cylinder(x,h+1.5,z,.65,2.0,palette.gold);b.cone(x,h+3,z,1.2,1.4,palette.steel,6)}if(obj.kind==='lamp'){b.cylinder(x,h,z,.21,6,palette.steel);b.oct(x,h+6.4,z,.8,palette.light,.95)}if(obj.kind==='beacon'){b.box(x,h,z,1.8,1.8,1.8,palette.steel2);b.oct(x,h+2.4,z,.8,palette.bright,1)}}
const s=b.finish();gl.bindBuffer(gl.ARRAY_BUFFER,staticBuffer);gl.bufferData(gl.ARRAY_BUFFER,s,gl.STATIC_DRAW);staticCount=s.length/10;creatures=[];spawnClock=0;collectorClock=0}
function makeHUD(){const build=root.querySelector('#hf3-craft');const options=['campfire','generator','collector','lamp','wall','beacon'];build.innerHTML=options.map(k=>`<button class="btn" data-action="build" data-kind="${k}" title="${esc(costLabel(k))}">${esc(NAMES[k])}<small>${esc(costLabel(k))}</small></button>`).join('');updateHUD()}
function updateHUD(){if(!current)return;const get=id=>root.querySelector('#'+id),p=current.player;
const set=(id,s)=>{const e=get(id);if(e)e.textContent=s};const meter=(id,val)=>{const e=get(id);if(e)e.style.width=clamp(val,0,100)+'%'};
set('hf3-date',`DAY ${String(current.day).padStart(2,'0')} · ${current.clock>.62||current.clock<.12?'NIGHT':current.clock>.48?'DUSK':'DAYLIGHT'}`);set('hf3-zone',current.scene==='home'?'THE OUTPOST':'LUMEN EXPEDITION');
set('hf3-hp-text',Math.ceil(p.hp));set('hf3-hunger-text',Math.ceil(p.hunger));set('hf3-stamina-text',Math.ceil(p.stamina));meter('hf3-hp',p.hp);meter('hf3-hunger',p.hunger);meter('hf3-stamina',p.stamina);
const closest=nearest();const distance=near(p,{x:current.scene==='home'?55:-13,z:current.scene==='home'?30:-6});
set('hf3-objective',current.scene==='expedition'?'Investigate the Lumen facility':current.relay?'The signal is live. Explore the frontier.':`Restore the Meridian relay (${Math.round(distance)}m away)`);
const wx=current.scene==='home'?55:-13,wz=current.scene==='home'?30:-6, bearing=Math.atan2(wx-p.x,wz-p.z)-camYaw;const wrap=Math.atan2(Math.sin(bearing),Math.cos(bearing)),arrow=Math.abs(wrap)<.4?'↑':Math.abs(wrap)>2.6?'↓':wrap>0?(wrap>1.45?'→':'↗'):(wrap< -1.45?'←':'↖');set('hf3-nearest',closest&&closest.d<6?`Nearby: ${closest.item.type} · Press E to collect`:(current.scene==='home'&&!current.relay&&distance<8?'Meridian relay: 12 scrap + 8 stone':`WAYPOINT ${arrow} · ${Math.round(distance)}m`));
const inv=get('hf3-inventory');if(inv)inv.innerHTML=TYPES.map(t=>`<span class="inv">${t.toUpperCase()}: <b>${num(current.inv[t])}</b></span>`).join('');
const power=gridPower();set('hf3-power',power.active?`ONLINE · ${power.active} powered generator${power.active===1?'':'s'} · ${power.collectors} extractors`:`OFFLINE · Fuel a generator to enable machinery`);
root.querySelectorAll('[data-action="build"]').forEach(b=>{b.classList.toggle('sel',b.dataset.kind===buildKind);b.disabled=current.scene==='expedition';b.title=costLabel(b.dataset.kind)});
const hint=get('hf3-hint');if(hint){hint.textContent=buildKind?`BUILD ${NAMES[buildKind].toUpperCase()}: click nearby ground to place · Esc to cancel`:closest&&closest.d<4.5?`E · COLLECT ${closest.item.type.toUpperCase()}`:current.scene==='home'&&near(p,{x:15,z:17})<5?'E · ENTER EXPEDITION':current.scene==='expedition'&&near(p,{x:0,z:0})<5?'E · RETURN HOME':`WASD move · drag to look · E interact · Shift sprint · J journal`;}
}
function nearest(){if(!current)return null;let best=null;for(const n of sceneNodes){if(n.qty<=0)continue;const d=near(current.player,n);if(!best||d<best.d)best={item:n,d}}return best}
function spend(cost){for(const [a,v] of Object.entries(cost))if(num(current.inv[a])<v)return false;for(const [a,v] of Object.entries(cost))current.inv[a]-=v;return true}
function gather(){const p=current.player,n=nearest();if(n&&n.d<4.5){n.item.qty--;current.depleted[n.item.id]=num(current.depleted[n.item.id])+1;current.inv[n.item.type]=(current.inv[n.item.type]||0)+((n.item.type==='wood'||n.item.type==='stone')?2:1);if(n.item.type==='lumen'&&!current.discoveries.includes('Lumen resonance'))current.discoveries.push('Lumen resonance');toast(`Collected ${n.item.type}.`);updateGeometry();save();return}
if(current.scene==='home'&&!current.relay&&near(p,{x:55,z:30})<8){if(!spend({scrap:12,stone:8})){toast('Relay repair requires 12 scrap and 8 stone.',4);return}current.relay=true;current.chapter=2;current.discoveries.push('The First Signal');updateGeometry();save();scene('relay');return}
if(current.scene==='home'&&near(p,{x:15,z:17})<6){expedition();return}
if(current.scene==='expedition'&&near(p,{x:0,z:0})<6){expedition();return}
if(current.scene==='expedition'&&near(p,{x:-13,z:-6})<7){current.inv.lumen++;current.discoveries.push('Below the Trees');toast('Lumen recovered. The tower contains a hidden Meridian record.');scene('lumen');save();return}
toast('Move closer to a resource or landmark.');}
function updateGeometry(){makeWorld();updateHUD()}
function craftScanner(){if(current.scanner){scan();return}if(spend(COST.scanner)){current.scanner=true;toast('Signal scanner crafted · press Space to scan.');save()}else toast('Scanner needs '+costLabel('scanner'))}
function scan(){if(!current.scanner){toast('Craft the signal scanner first.');return}scanTime=3;const list=sceneNodes.filter(n=>n.qty>0&&near(n,current.player)<25).sort((a,b)=>near(a,current.player)-near(b,current.player));toast(list.length?`Scanner: ${list.length} signals nearby · closest is ${list[0].type} (${Math.round(near(list[0],current.player))}m)`:'Scanner: no nearby resource signals.',4)}
function gridPower(){const active=current.buildings.filter(b=>b.kind==='generator'&&(b.fuel||0)>0).length;return {active,collectors:current.buildings.filter(b=>b.kind==='collector').length,lamps:current.buildings.filter(b=>b.kind==='lamp').length}}
function fuel(){if(current.scene!=='home'){toast('Return to your settlement to fuel machines.');return}const g=current.buildings.find(b=>b.kind==='generator');if(!g){toast('Build a generator first.');return}if(!spend({wood:1})){toast('Requires 1 wood.');return}g.fuel=(g.fuel||0)+95;toast('Generator fueled for 95 seconds.');updateGeometry();save()}
function eat(){if(!spend({berry:1})){toast('You need berries.');return}current.player.hunger=clamp(current.player.hunger+24,0,100);current.player.hp=clamp(current.player.hp+8,0,100);toast('Ate berries · hunger restored.');save()}
function placeFromPointer(event){const screen=root.querySelector('#hf3-screen'),r=canvas.getBoundingClientRect(),uvx=((event.clientX-r.left)/r.width)*2-1,uvy=1-((event.clientY-r.top)/r.height)*2;if(uvx< -1||uvx>1||uvy< -1||uvy>1)return;const ray=makeCamera(),tan=Math.tan(Math.PI/6);const dir=norm([ray.forward[0]+ray.right[0]*uvx*ray.aspect*tan+ray.up[0]*uvy*tan,ray.forward[1]+ray.right[1]*uvx*ray.aspect*tan+ray.up[1]*uvy*tan,ray.forward[2]+ray.right[2]*uvx*ray.aspect*tan+ray.up[2]*uvy*tan]);if(dir[1]>=-.05){toast('Aim at the ground near your character.');return}
let t=(terrain(current.player.x,current.player.z)-ray.eye[1])/dir[1];for(let i=0;i<4;i++){const x=ray.eye[0]+dir[0]*t,z=ray.eye[2]+dir[2]*t;t=(terrain(x,z)-ray.eye[1])/dir[1]}const x=ray.eye[0]+dir[0]*t,z=ray.eye[2]+dir[2]*t;buildAt(x,z)}
function buildAt(x,z){if(!buildKind)return;if(current.scene!=='home'){toast('Build in your home settlement.');return}if(!Number.isFinite(x)||!Number.isFinite(z)||Math.hypot(x,z)>105){toast('Select a location inside the frontier.');return}if(Math.hypot(x-current.player.x,z-current.player.z)>14){toast('Build closer to your explorer (within 14m).');return}if(Math.hypot(x-55,z-30)<8||Math.hypot(x-15,z-17)<5){toast('Keep expedition and relay sites clear.');return}if(!spend(COST[buildKind])){toast('Need '+costLabel(buildKind));return}current.buildings.push({kind:buildKind,x:Math.round(x*10)/10,z:Math.round(z*10)/10,fuel:0});toast(`${NAMES[buildKind]} constructed.`);buildKind=null;updateGeometry();save()}
function expedition(){if(current.scene==='home'){if(!current.relay){toast('Repair the Meridian relay before your first Lumen expedition.');return}current.scene='expedition';current.player.x=0;current.player.z=0;current.discoveries.push('Lumen expedition');scene('expedition')}else{current.scene='home';current.player.x=15;current.player.z=20;toast('You returned to your settlement.')}buildKind=null;makeWorld();save();updateHUD()}
function damage(amount){current.player.hp=clamp(current.player.hp-amount,0,100);if(current.player.hp<=0){current.player.hp=100;current.player.hunger=70;current.player.x=current.scene==='home'?0:0;current.player.z=0;creatures=[];toast('You retreated to safety. Your world and structures were preserved.',6);save()}}
function dialog(html){showDialog=true;const el=root.querySelector('#hf3-modal');if(el)el.innerHTML=`<div class="modal"><div class="dialog">${html}</div></div>`}
function closeDialog(){showDialog=false;keys.clear();mobileKeys.clear();cutscene=null;modalKind='';const e=root.querySelector('#hf3-modal');if(e)e.replaceChildren()}
const SCENES={arrival:[['PROLOGUE / THE ARRIVAL','The sky flickered above the tree line. Then the transport went silent.','Recovery Team Seven was supposed to retrieve missing Meridian research records. Instead, your crew has disappeared and the wilderness has no signal.'],['TRANSMISSION / UNKNOWN SOURCE','“If you can hear this, do not activate the final relay.”','The voice cuts out. An old emergency beacon pulses somewhere to the east.'],['OBJECTIVE / DAY ONE','Survive. Build. Uncover the signal.','Gather wood and stone, craft a scanner, and follow the path toward the abandoned Meridian relay.']],relay:[['CHAPTER I / THE FIRST SIGNAL','A forgotten tower awakens.','Buried beneath static, a research recording repeats: “Lumen responds to the machinery. It was never meant to be controlled.”'],['MERIDIAN ARCHIVE / RECORD 07','The forest is listening.','New routes have opened. Enter the Lumen expedition platform to investigate a lost laboratory.']],expedition:[['EXPEDITION / BELOW THE TREES','The signal becomes clearer underground.','The Lumen readings are stronger here. Find the abandoned research facility and recover its records.']],lumen:[['CHAPTER II / THE HOLLOW NETWORK','Lumen is more than energy.','The recovered record suggests the Frontier is a living network. Every machine you build changes how it reacts.']]};
function scene(k){modalKind='scene';cutscene={key:k,index:0};showScene()}
function showScene(){const sc=SCENES[cutscene.key]||SCENES.arrival,n=sc[cutscene.index];if(!n){if(cutscene.key==='arrival'&&current.chapter===0){current.chapter=1;save()}closeDialog();return}dialog(`<div class="overline">${esc(n[0])} · ${cutscene.index+1}/${sc.length}</div><h2>${esc(n[1])}</h2><p>${esc(n[2])}</p><footer><button class="btn accent" data-action="scene-next">${cutscene.index===sc.length-1?'Begin exploration':'Continue →'}</button><button class="btn" data-action="scene-skip">Skip cinematic</button></footer>`)}
function journal(){modalKind='journal';const text=current.discoveries.slice(-30).map((s,i)=>`<p><strong>ENTRY ${String(i+1).padStart(2,'0')}</strong> · ${esc(s)}</p>`).join('');dialog(`<div class="overline">MERIDIAN FIELD ARCHIVE</div><h2>Frontier Journal</h2><p>Discoveries belong to this world slot. Scan objects, restore the relay and venture beyond the Outpost to find more records.</p><div class="journal">${text}</div><footer><button class="btn accent" data-action="close">Return to the frontier</button><button class="btn" data-action="backup">Export world backup</button></footer>`)}
function help(){modalKind='help';dialog(`<div class="overline">3D SURVIVAL FIELD GUIDE</div><h2>Explore the Frontier</h2><p><b>WASD / arrow keys</b> move. <b>Shift</b> sprints. Drag across the world to orbit the camera; scroll to change height. <b>V</b> switches first/third person. <b>E</b> gathers nearby supplies and activates landmarks. <b>Space</b> scans once crafted; <b>J</b> opens the journal.</p><p>Build structures using the Craft panel and click the ground near your explorer. Fuel generators with wood. Powered extractors automatically generate stone and scrap. Your settlement persists when you return from expeditions.</p><p><b>Saving:</b> Each of your three free worlds stays in this browser. Export a backup from the Journal and restore it on the world-selection screen. Save data is not shared with Roblox or other devices.</p><footer><button class="btn accent" data-action="close">Start playing</button></footer>`)}
function backup(){const json=JSON.stringify({type:'hollow-frontier-3d-save',version:2,world:current},null,2);const u=URL.createObjectURL(new Blob([json],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=`hollow-frontier-world-${slot+1}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1500);toast('Backup exported. Keep it somewhere safe.');}
function soundtrack(){if(audioOn){audio?.suspend();audioOn=false}else{try{const AC=window.AudioContext||window.webkitAudioContext;if(!audio){audio=new AC();const osc=audio.createOscillator(),osc2=audio.createOscillator(),g=audio.createGain();osc.type='sine';osc.frequency.value=57;osc2.type='sine';osc2.frequency.value=86;g.gain.value=.014;osc.connect(g);osc2.connect(g);g.connect(audio.destination);osc.start();osc2.start()}audio.resume();audioOn=true}catch{toast('Audio unavailable on this device.')}}root.querySelector('[data-action="audio"]').textContent=audioOn?'AUDIO ON':'AUDIO OFF'}
function keyDown(e){if(!current)return;const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys.add(k);if(e.repeat)return;if(showDialog){if(k==='escape'){closeDialog();return}if(k==='enter'&&cutscene){cutscene.index++;showScene()}return}if(k==='e')gather();else if(k===' ')scan();else if(k==='j')journal();else if(k==='v')third=!third;else if(k==='escape')buildKind=null;}
function keyUp(e){keys.delete(e.key.toLowerCase())}
root.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||!root.contains(b))return;const a=b.dataset.action;if(a==='slot'){openWorld(num(b.dataset.index));return}if(a==='classic'){loadClassic();return}if(a==='menu'){if(current)save();home();return}if(!current)return;if(a==='save'){save();toast('World saved to this browser.');return}if(a==='scene-next'){cutscene.index++;showScene();return}if(a==='scene-skip'||a==='close'){if(cutscene?.key==='arrival'&&current.chapter===0){current.chapter=1;save()}closeDialog();return}if(a==='backup'){backup();return}if(showDialog)return;if(a==='pack'){root.querySelector('.screen')?.classList.toggle('show-pack');return}if(a==='build'){buildKind=(buildKind===b.dataset.kind?null:b.dataset.kind);root.querySelector('.screen')?.classList.remove('show-pack');updateHUD();return}if(a==='interact'){gather();return}if(a==='eat'){eat();return}if(a==='scanner'){craftScanner();return}if(a==='scan'){scan();return}if(a==='fuel'){fuel();return}if(a==='journal'){journal();return}if(a==='expedition'){expedition();return}if(a==='camera'){third=!third;toast(third?'Third-person camera':'First-person camera');return}if(a==='turn'){camYaw+=Math.PI/5;return}if(a==='help'){help();return}if(a==='fullscreen'){const s=root.querySelector('#hf3-screen');if(document.fullscreenElement)document.exitFullscreen?.();else s.requestFullscreen?.().catch(()=>toast('Fullscreen is unavailable here.'));return}if(a==='audio'){soundtrack();return}});
function resize(){if(!canvas||!gl)return;const r=canvas.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,1.7),w=Math.max(320,Math.round(r.width*dpr)),h=Math.max(200,Math.round(r.height*dpr));if(w!==canvas.width||h!==canvas.height){canvas.width=w;canvas.height=h;width=w;height=h;gl.viewport(0,0,w,h)}}
function makeCamera(){const p=current.player,ground=terrain(p.x,p.z);const target=[p.x,ground+(third?2.25:1.7),p.z],distance=third?17:.11;const eye=third?[p.x-Math.sin(camYaw)*Math.cos(camPitch)*distance,ground+2.25+Math.sin(camPitch)*distance,p.z-Math.cos(camYaw)*Math.cos(camPitch)*distance]:[p.x,ground+1.7,p.z];const forward=norm(sub(target,eye)),right=norm(cross(forward,[0,1,0])),up=norm(cross(right,forward));return {eye,target,forward,right,up,aspect:Math.max(.5,width/Math.max(1,height))}}
function lighting(){const c=current.clock;const daylight=clamp(Math.sin((c-.12)*Math.PI*2)*.92+.15,.05,1);sun=daylight;ambient=.2+sun*.8;const dusk=Math.max(0,1-Math.abs(c-.65)*8);const r=.08+sun*.54+dusk*.25,g=.13+sun*.62+dusk*.09,b=.19+sun*.66;return [r,g,b]}
function render(){if(!gl||!current)return;resize();const sky=lighting();root.querySelector('#hf3-screen')?.classList.toggle('storm',current.day%5===3&&current.clock>.3&&current.clock<.75);gl.viewport(0,0,width,height);gl.clearColor(sky[0],sky[1],sky[2],1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.useProgram(program);
const cam=makeCamera(),vp=multiply(perspective(Math.PI/3,cam.aspect,.12,350),lookAt(cam.eye,cam.target));gl.uniformMatrix4fv(uniforms.uVP,false,new Float32Array(vp));gl.uniform3fv(uniforms.uCamera,new Float32Array(cam.eye));gl.uniform3fv(uniforms.uSun,new Float32Array([.52,.86,.34]));gl.uniform3fv(uniforms.uFog,new Float32Array(sky));gl.uniform1f(uniforms.uDay,sun);
const powered=current.scene==='home'&&gridPower().active>0;const lamp=current.buildings.find(b=>b.kind==='lamp');const fire=current.scene==='home'?current.buildings.find(b=>b.kind==='campfire'):null;const glow=powered&&lamp?lamp:fire;gl.uniform3fv(uniforms.uLamp,new Float32Array(glow?[glow.x,terrain(glow.x,glow.z)+3,glow.z]:[0,0,0]));gl.uniform1f(uniforms.uHasLamp,glow?1:0);
for(const [buffer,count] of [[terrainBuffer,terrainCount],[staticBuffer,staticCount]]){bind(buffer);gl.drawArrays(gl.TRIANGLES,0,count)}
const b=new Builder(),p=current.player,t=performance.now()/1000;const y=terrain(p.x,p.z);if(third){const stride=Math.sin(motion*11)*.35;b.box(p.x,y+.25,p.z,.57,.87,.57,palette.steel2);b.box(p.x-.22,y+.32+stride*.18,p.z,.31,.83,.34,palette.player);b.box(p.x+.22,y+.32-stride*.18,p.z,.31,.83,.34,palette.player);b.box(p.x,y+1.05,p.z,.98,.93,.56,palette.gold);b.box(p.x,y+2.0,p.z,.73,.66,.7,palette.player);b.box(p.x,y+2.2,p.z+.37,.52,.20,.1,palette.bright,.3);b.box(p.x+.56,y+1.1,p.z,.28,.55,.35,palette.steel)}
for(const e of creatures){const h=terrain(e.x,e.z);b.cone(e.x,h,e.z,.70,2.5,palette.shadow);b.oct(e.x,h+2.7+Math.sin(t*2+e.x)*.13,e.z,.62,palette.shadow);b.oct(e.x-.24,h+2.76,e.z+.48,.12,palette.bright,1);b.oct(e.x+.24,h+2.76,e.z+.48,.12,palette.bright,1)}
if(scanTime>0){for(const n of sceneNodes){if(n.qty<=0||near(n,p)>24)continue;b.oct(n.x,terrain(n.x,n.z)+2.3+Math.sin(t*4+n.x)*.3,n.z,.37,palette.bright,1.2)}}
const data=b.finish();gl.bindBuffer(gl.ARRAY_BUFFER,dynamicBuffer);gl.bufferData(gl.ARRAY_BUFFER,data,gl.DYNAMIC_DRAW);bind(dynamicBuffer);gl.drawArrays(gl.TRIANGLES,0,data.length/10)}
function frame(now){if(!current||!gl)return;const dt=clamp((now-lastTick)/1000,0,.055);lastTick=now;if(!showDialog)tick(dt);render();uiClock+=dt;if(uiClock>.28){uiClock=0;updateHUD()}const toastEl=root.querySelector('#hf3-toast');if(toastEl)toastEl.hidden=now>toastUntil;raf=requestAnimationFrame(frame)}
function tick(dt){const p=current.player;let forward=0,side=0;const down=k=>keys.has(k)||mobileKeys.has(k);if(down('w')||down('arrowup')||down('up'))forward++;if(down('s')||down('arrowdown')||down('down'))forward--;if(down('a')||down('arrowleft')||down('left'))side--;if(down('d')||down('arrowright')||down('right'))side++;
const sprint=(keys.has('shift')&&p.stamina>2&&forward>0),length=Math.hypot(forward,side)||1;forward/=length;side/=length;const speed=sprint?10.5:6;let mx=(Math.sin(camYaw)*forward+Math.cos(camYaw)*side)*speed*dt,mz=(Math.cos(camYaw)*forward-Math.sin(camYaw)*side)*speed*dt;
const nx=clamp(p.x+mx,-104,104),nz=clamp(p.z+mz,-104,104);p.x=nx;p.z=nz;if(Math.hypot(mx,mz)>.001){motion+=dt;p.stamina=clamp(p.stamina-(sprint?11*dt:0)+(!sprint?8*dt:0),0,100);playerHeading=Math.atan2(mx,mz)}else p.stamina=clamp(p.stamina+10*dt,0,100);
const oldNight=current.clock>.63||current.clock<.12;current.clock+=dt/CYCLE;if(current.clock>=1){current.clock-=1;current.day++;if(current.scene==='expedition')current.expNights=(current.expNights||0)+1;toast(`Day ${current.day}. The frontier is still watching.`,5);save()}
const night=current.clock>.63||current.clock<.12;p.hunger=clamp(p.hunger-dt*.19-(sprint?dt*.1:0),0,100);if(p.hunger<1)damage(dt*.9);
if(night&&!oldNight)toast('Night is falling. The Watchers emerge.',5);spawnClock+=dt;if(night&&spawnClock>19&&creatures.length<3){spawnClock=0;const a=Math.random()*Math.PI*2,d=19+Math.random()*14;creatures.push({x:clamp(p.x+Math.cos(a)*d,-100,100),z:clamp(p.z+Math.sin(a)*d,-100,100),timer:0})}if(!night)creatures=creatures.filter(e=>near(p,e)<12);
for(const e of creatures){let dx=p.x-e.x,dz=p.z-e.z,d=Math.hypot(dx,dz)||1;const danger=gridPower().active>0&&current.scene==='home'?1.18:1;let repel=false;for(const l of current.scene==='home'?current.buildings:[]){if(l.kind==='campfire'||(l.kind==='lamp'&&gridPower().active)){if(Math.hypot(l.x-e.x,l.z-e.z)<13){repel=true;dx=e.x-l.x;dz=e.z-l.z;d=Math.hypot(dx,dz)||1;break}}}const speedE=repel?3:1.5*danger;e.x=clamp(e.x+dx/d*dt*speedE,-108,108);e.z=clamp(e.z+dz/d*dt*speedE,-108,108);if(near(p,e)<1.8){e.timer+=dt;if(e.timer>1.3){damage(5);e.timer=0;toast('A Watcher found you. Head toward the light!')}}}
if(current.scene==='home'){let powered=false;for(const b of current.buildings)if(b.kind==='generator'&&b.fuel>0){b.fuel=Math.max(0,b.fuel-dt);powered=true}if(powered){collectorClock+=dt;if(collectorClock>19){collectorClock=0;const cnt=current.buildings.filter(b=>b.kind==='collector').length;if(cnt){current.inv.stone+=cnt;current.inv.scrap+=cnt;toast(`Extractor network delivered ${cnt} stone and ${cnt} scrap.`);save()}}}}
scanTime=Math.max(0,scanTime-dt);autosave+=dt;if(autosave>20){autosave=0;save()}}
// Debug harness intentionally exposed only on localhost for repeatable QA smoke tests.
if(location.hostname==='localhost'||location.hostname==='127.0.0.1'||window.__HF_TEST__)window.HollowFrontier3DTest={get:()=>current,slot:()=>slot,advance:dt=>tick(dt),place:(k,x,z)=>{buildKind=k;buildAt(x,z)},gather,expedition,save,webgl:()=>!!gl};
home();
